const startUpload = async (toUpload: UploadQueueItem[]) => {
  const id = await createUploadBatch();
  clearItems((item) => item.source === 'content-library' && isBlockedFromUpload(item) && !item.cloudUpload);
  for (const item of toUpload) updateItem(item.id, { replacesDocumentId: item.replacesDocumentId });
  startCloudUploads(toUpload, id);
  setBatchId(id);
  setStep('uploading');
};

const answers = await checkDuplicates(
  pending.map((item) => {
    const payload: Parameters<typeof checkDuplicates>[0][number] = {
      filename: item.name,
      fileSize: item.size,
    };
    if (item.extension === 'zip' && item.validation?.zipEntries?.length) {
      payload.entries = item.validation.zipEntries.map((entry) => ({
        name: entry.path,
        fileSize: entry.size,
      }));
    }
    return payload;
  }),
);
